import { Model } from '@nozbe/watermelondb';
import { date, field, json, relation } from '@nozbe/watermelondb/decorators';

import { sanitizer } from '../utils';

export const THREAD_MESSAGES_TABLE = 'thread_messages';

export default class ThreadMessage extends Model {
	static table = THREAD_MESSAGES_TABLE;

	static associations = {
		subscriptions: { type: 'belongs_to', key: 'subscription_id' }
	};

	@field('msg') msg;

	@field('t') t;

	@date('ts') ts;

	@json('u', sanitizer, { memo: true }) u;

	@relation('subscriptions', 'subscription_id') subscription;

	@field('rid') rid;

	@field('alias') alias;

	@json('parse_urls', sanitizer, { memo: true }) parseUrls;

	@field('groupable') groupable;

	@field('avatar') avatar;

	@field('emoji') emoji;

	@json('attachments', sanitizer, { memo: true }) attachments;

	@json('urls', sanitizer, { memo: true }) urls;

	@date('_updated_at') _updatedAt;

	@field('status') status;

	@field('pinned') pinned;

	@field('starred') starred;

	@json('edited_by', sanitizer, { memo: true }) editedBy;

	@json('reactions', sanitizer, { memo: true }) reactions;

	@field('role') role;

	@field('drid') drid;

	@field('dcount') dcount;

	@date('dlm') dlm;

	@field('tcount') tcount;

	@date('tlm') tlm;

	@json('replies', sanitizer, { memo: true }) replies;

	@json('mentions', sanitizer, { memo: true }) mentions;

	@json('channels', sanitizer, { memo: true }) channels;

	@field('unread') unread;

	@field('auto_translate') autoTranslate;

	@json('translations', sanitizer, { memo: true }) translations;

	@field('draft_message') draftMessage;

	@field('e2e') e2e;

	@json('content', sanitizer, { memo: true }) content;

	asPlain() {
		return {
			id: this.id,
			msg: this.msg,
			t: this.t,
			ts: this.ts,
			u: this.u,
			rid: this.rid,
			alias: this.alias,
			parseUrls: this.parseUrls,
			groupable: this.groupable,
			avatar: this.avatar,
			emoji: this.emoji,
			attachments: this.attachments,
			urls: this.urls,
			_updatedAt: this._updatedAt,
			status: this.status,
			pinned: this.pinned,
			starred: this.starred,
			editedBy: this.editedBy,
			reactions: this.reactions,
			role: this.role,
			drid: this.drid,
			dcount: this.dcount,
			dlm: this.dlm,
			tcount: this.tcount,
			tlm: this.tlm,
			replies: this.replies,
			mentions: this.mentions,
			channels: this.channels,
			unread: this.unread,
			autoTranslate: this.autoTranslate,
			translations: this.translations,
			draftMessage: this.draftMessage,
			e2e: this.e2e,
			content: this.content
		};
	}
}

import { store as reduxStore } from '../../store/auxStore';
import sdk from '../sdk';
import { getThreadMessages } from '../restApi';

jest.mock('../../store/auxStore', () => ({
	store: {
		getState: jest.fn()
	}
}));

jest.mock('../sdk', () => ({
	__esModule: true,
	default: {
		get: jest.fn(),
		methodCallWrapper: jest.fn()
	}
}));

const mockedGet = sdk.get as jest.Mock;
const mockedMethodCallWrapper = sdk.methodCallWrapper as jest.Mock;

const setServerVersion = (version: string) => (reduxStore.getState as jest.Mock).mockReturnValue({ server: { version } });

describe('getThreadMessages', () => {
	beforeEach(() => {
		jest.clearAllMocks();
		setServerVersion('8.8.0');
	});

	it('requests a newest-first page of the given size on 8.8.0+ and leaves the parent to the caller', async () => {
		mockedGet.mockResolvedValueOnce({ messages: [{ _id: 'tm1' }], count: 1, offset: 0, total: 80, success: true });

		const result = await getThreadMessages({ tmid: 'tmid', offset: 0, count: 25 });

		expect(mockedGet).toHaveBeenCalledTimes(1);
		expect(mockedGet).toHaveBeenCalledWith('chat.getThreadMessages', { tmid: 'tmid', count: 25, offset: 0, sort: { ts: -1 } });
		expect(mockedMethodCallWrapper).not.toHaveBeenCalled();
		expect(result).toEqual({ messages: [{ _id: 'tm1' }], total: 80, threadParent: null });
	});

	it('throws when the page request is not successful', async () => {
		mockedGet.mockResolvedValueOnce({ success: false });

		await expect(getThreadMessages({ tmid: 'tmid', offset: 0, count: 50 })).rejects.toThrow();
	});

	it('loads the whole thread with the getThreadMessages DDP method on 8.7.x and separates the parent from the replies', async () => {
		setServerVersion('8.7.9');
		mockedMethodCallWrapper.mockResolvedValueOnce([{ _id: 'tmid' }, { _id: 'tm1' }, { _id: 'tm2' }]);

		const result = await getThreadMessages({ tmid: 'tmid', offset: 0, count: 50 });

		expect(mockedMethodCallWrapper).toHaveBeenCalledWith('getThreadMessages', { tmid: 'tmid' });
		expect(mockedGet).not.toHaveBeenCalled();
		expect(result).toEqual({ messages: [{ _id: 'tm1' }, { _id: 'tm2' }], total: 2, threadParent: { _id: 'tmid' } });
	});

	it('returns no parent on 8.7.x when the DDP method does not return it', async () => {
		setServerVersion('8.7.9');
		mockedMethodCallWrapper.mockResolvedValueOnce([{ _id: 'tm1' }]);

		expect(await getThreadMessages({ tmid: 'tmid', offset: 0, count: 50 })).toEqual({
			messages: [{ _id: 'tm1' }],
			total: 1,
			threadParent: null
		});
	});

	it('returns an empty thread when the DDP method returns nothing', async () => {
		setServerVersion('8.7.9');
		mockedMethodCallWrapper.mockResolvedValueOnce(null);

		expect(await getThreadMessages({ tmid: 'tmid', offset: 0, count: 50 })).toEqual({
			messages: [],
			total: 0,
			threadParent: null
		});
	});
});

import { fireEvent, render, screen } from '@testing-library/react-native';

import { AttachmentActionSheet } from './AttachmentActionSheet';
import { type IShareAttachment } from '~/definitions';
import { generateSnapshots } from '~/.rnstorybook/generateSnapshots';
import * as stories from './AttachmentActionSheet.stories';

jest.mock('react-native-keyboard-controller', () => {
	const { View } = require('react-native');
	return { KeyboardAwareScrollView: View };
});

jest.mock('react-native-safe-area-context', () => ({
	useSafeAreaInsets: () => ({ top: 0, bottom: 0, left: 0, right: 0 })
}));

jest.mock('~/containers/ActionSheet', () => ({
	useActionSheet: jest.fn()
}));

jest.mock('~/lib/hooks/useAltTextSupported', () => ({
	useAltTextSupported: jest.fn()
}));

const mockUseActionSheet = require('~/containers/ActionSheet').useActionSheet as jest.Mock;
const mockUseAltTextSupported = require('~/lib/hooks/useAltTextSupported').useAltTextSupported as jest.Mock;

const baseAttachment: IShareAttachment = {
	filename: 'photo.png',
	size: 1024,
	mime: 'image/png',
	path: 'file:///tmp/photo.png'
};

describe('AttachmentActionSheet', () => {
	const hideActionSheet = jest.fn();

	beforeEach(() => {
		jest.clearAllMocks();
		mockUseActionSheet.mockReturnValue({ hideActionSheet });
		mockUseAltTextSupported.mockReturnValue(true);
	});

	it('renders the attachment filename', () => {
		render(<AttachmentActionSheet attachment={baseAttachment} onSave={jest.fn()} />);

		expect(screen.getByText('photo.png')).toBeOnTheScreen();
	});

	it('shows alt text input for image attachments when supported by the server', () => {
		render(<AttachmentActionSheet attachment={baseAttachment} onSave={jest.fn()} />);

		expect(screen.getByLabelText('Alternative text')).toBeOnTheScreen();
	});

	it('hides alt text input when the server does not support it', () => {
		mockUseAltTextSupported.mockReturnValue(false);

		render(<AttachmentActionSheet attachment={baseAttachment} onSave={jest.fn()} />);

		expect(screen.queryByLabelText('Alternative text')).toBeNull();
	});

	it('hides alt text input for non-image attachments', () => {
		render(
			<AttachmentActionSheet attachment={{ ...baseAttachment, filename: 'clip.mp4', mime: 'video/mp4' }} onSave={jest.fn()} />
		);

		expect(screen.queryByLabelText('Alternative text')).toBeNull();
	});

	it('prefills the input with the existing altText', () => {
		render(<AttachmentActionSheet attachment={{ ...baseAttachment, altText: 'A cat on a sofa' }} onSave={jest.fn()} />);

		expect(screen.getByLabelText('Alternative text').props.value).toBe('A cat on a sofa');
	});

	it('calls onSave with the typed altText and hides the action sheet', () => {
		const onSave = jest.fn();
		render(<AttachmentActionSheet attachment={baseAttachment} onSave={onSave} />);

		fireEvent.changeText(screen.getByLabelText('Alternative text'), 'A red apple');
		fireEvent.press(screen.getByText('Save'));

		expect(onSave).toHaveBeenCalledWith({ altText: 'A red apple' });
		expect(hideActionSheet).toHaveBeenCalledTimes(1);
	});

	it('saves an empty altText when the server does not support it', () => {
		mockUseAltTextSupported.mockReturnValue(false);
		const onSave = jest.fn();

		render(<AttachmentActionSheet attachment={baseAttachment} onSave={onSave} />);
		fireEvent.press(screen.getByText('Save'));

		expect(onSave).toHaveBeenCalledWith({ altText: '' });
		expect(hideActionSheet).toHaveBeenCalledTimes(1);
	});
});

