import { getSupportedVersionsCloud } from '../restApi';
import { applyBasicAuth } from '~/lib/methods/serverBasicAuth';
import { setSharedAuthorizationOrigin } from '~/lib/methods/helpers/fetch';
import UserPreferences from '~/lib/methods/userPreferences';
import { getBasicAuthKey } from '~/lib/constants/keys';
import { mockGlobalFetch } from '~/lib/testUtils/mockGlobalFetch';

describe('getSupportedVersionsCloud', () => {
	const workspace = 'https://workspace.example';
	const sentToNetwork = mockGlobalFetch(() => Promise.resolve({} as Response));

	beforeEach(() => {
		UserPreferences.setString(getBasicAuthKey(workspace), 'current-workspace');
		applyBasicAuth(workspace);
	});

	afterEach(() => {
		UserPreferences.removeItem(getBasicAuthKey(workspace));
		setSharedAuthorizationOrigin(null);
	});

	it('does not send the current workspace basic auth to the cloud', async () => {
		await getSupportedVersionsCloud('unique-id', workspace);

		expect(sentToNetwork).toHaveBeenCalledTimes(1);
		expect(sentToNetwork.mock.calls[0][0]).toContain('https://releases.rocket.chat/v2/server/supportedVersions');
		expect(sentToNetwork.mock.calls[0][1].headers).not.toHaveProperty('Authorization');
	});

	it('passes the abort signal to the request', async () => {
		const controller = new AbortController();

		await getSupportedVersionsCloud('unique-id', workspace, controller.signal);

		expect(sentToNetwork.mock.calls[0][1].signal).toBe(controller.signal);
	});
});

import fs from 'fs';
import path from 'path';

// MessageStore's Object.is/useShallow bail-outs depend on every @json field returning a stable
// reference for an unchanged record. That stability comes only from WatermelonDB's `{ memo: true }`
// decorator option (app/containers/message/stores/MessageStore.tsx:62-67). This is a source
// characterization test: it can't observe the runtime accessor without an LDB mock, so it guards
// the textual invariant instead.
const messageSource = fs.readFileSync(path.join(__dirname, '../Message.js'), 'utf8');

describe('Message.js @json memo invariant', () => {
	const jsonDeclarations = messageSource.match(/@json\([^)]*\)/g) ?? [];

	// Positive control: a regex that matches nothing would let every assertion below pass vacuously.
	it('finds the expected number of @json fields', () => {
		expect(jsonDeclarations.length).toBe(13);
	});

	it('declares { memo: true } on every @json field', () => {
		expect(jsonDeclarations.length).toBeGreaterThan(0);
		jsonDeclarations.forEach(declaration => {
			expect(declaration).toContain('{ memo: true }');
		});
	});
});

import Subscription from '../Subscription';

// RoomStore's field selectors depend on an unchanged @json field returning the same reference
// across observe() emits; that stability comes from WatermelonDB's `{ memo: true }` option.
const makeRecord = (raw: Record<string, unknown>) => {
	const record = Object.create(Subscription.prototype);
	record._raw = raw;
	return record;
};

describe.each([
	['tunread', 'tunread', JSON.stringify(['1', '2']), JSON.stringify(['1', '2', '3'])],
	['tunreadUser', 'tunread_user', JSON.stringify(['1']), JSON.stringify(['1', '2'])],
	['tunreadGroup', 'tunread_group', JSON.stringify(['1']), JSON.stringify(['1', '2'])],
	['visitor', 'visitor', JSON.stringify({ status: 'online' }), JSON.stringify({ status: 'away' })],
	['source', 'source', JSON.stringify({ type: 'app' }), JSON.stringify({ type: 'widget' })],
	[
		'abacAttributes',
		'abac_attributes',
		JSON.stringify([{ key: 'k', values: ['v'] }]),
		JSON.stringify([{ key: 'k', values: ['v', 'w'] }])
	],
	['ignored', 'ignored', JSON.stringify(['uid-1']), JSON.stringify(['uid-1', 'uid-2'])],
	['lastMessage', 'last_message', JSON.stringify({ msg: 'hi' }), JSON.stringify({ msg: 'bye' })]
])('Subscription %s @json memo', (field, column, rawValue, changedRawValue) => {
	it('returns the identical reference on repeated reads', () => {
		const record = makeRecord({ [column]: rawValue });

		expect(record[field]).toBe(record[field]);
	});

	it('returns a new reference after the raw column value changes', () => {
		const record = makeRecord({ [column]: rawValue });

		const before = record[field];
		record._raw[column] = changedRawValue;
		const after = record[field];

		expect(after).not.toBe(before);
	});

	it('keeps the same reference when an unrelated column changes', () => {
		const record = makeRecord({ [column]: rawValue, unread: 0 });

		const before = record[field];
		record._raw.unread = 1;
		const after = record[field];

		expect(after).toBe(before);
	});
});

