		mockedGetThreadMessages.mockResolvedValueOnce(page(4, 'R2'));
		await loadOlderThreadMessages(thread);
		await loadFirstPage(4, 'R1');
		mockedGetThreadMessages.mockClear();

		await expect(loadThreadMessagesUntil(thread, target('R2'), wanted)).resolves.toBe(true);

		expect(mockedGetThreadMessages).not.toHaveBeenCalled();
	});

	it('pages again from the reloaded first page when the thread changed since it was last loaded', async () => {
		await loadFirstPage(4, 'R1');
		mockedGetThreadMessages.mockResolvedValueOnce(page(4, 'R2'));
		await loadOlderThreadMessages(thread);

		await loadFirstPage(5, 'R0');
		mockedGetThreadMessages.mockResolvedValueOnce(page(5, 'R1'));
		await loadOlderThreadMessages(thread);

		expect(mockedGetThreadMessages).toHaveBeenLastCalledWith({ tmid: thread.tmid, offset: 1, count: 50 });
	});

	it('forgets the reached oldest page once the thread view closes', async () => {
		const closeView = retainThreadPagination(thread.tmid);
		await loadFirstPage(2, 'R1');
		mockedGetThreadMessages.mockResolvedValueOnce(page(2, 'R2'));
		await loadOlderThreadMessages(thread);

		closeView();
		await loadFirstPage(2, 'R1');

		expect(areOlderThreadMessagesMissing(thread.tmid)).toBe(true);
	});

	it('forgets the reached oldest page of a thread no view retained once it is released', async () => {
		await loadFirstPage(2, 'R1');
		mockedGetThreadMessages.mockResolvedValueOnce(page(2, 'R2'));
		await loadOlderThreadMessages(thread);

		releaseUnretainedThreadPagination(thread.tmid);
		await loadFirstPage(2, 'R1');

		expect(areOlderThreadMessagesMissing(thread.tmid)).toBe(true);
	});

	it('keeps the reached oldest page of a retained thread when the release is requested', async () => {
		retainThreadPagination(thread.tmid);
		await loadFirstPage(2, 'R1');
		mockedGetThreadMessages.mockResolvedValueOnce(page(2, 'R2'));
		await loadOlderThreadMessages(thread);

		releaseUnretainedThreadPagination(thread.tmid);
		await loadFirstPage(2, 'R1');

		expect(areOlderThreadMessagesMissing(thread.tmid)).toBe(false);
	});

	it('keeps the reached oldest page until the last view of the thread closes', async () => {
		const closeFirstView = retainThreadPagination(thread.tmid);
		const closeSecondView = retainThreadPagination(thread.tmid);
		await loadFirstPage(2, 'R1');
		mockedGetThreadMessages.mockResolvedValueOnce(page(2, 'R2'));
		await loadOlderThreadMessages(thread);

		closeFirstView();
		await loadFirstPage(2, 'R1');
		expect(areOlderThreadMessagesMissing(thread.tmid)).toBe(false);

		closeSecondView();
		await loadFirstPage(2, 'R1');
		expect(areOlderThreadMessagesMissing(thread.tmid)).toBe(true);
	});

	it('does not reuse an older page left in flight by a closed thread view as the first page', async () => {
		const closeView = retainThreadPagination(thread.tmid);
		await loadFirstPage(5, 'R1');
		const releaseOlder = deferPage();
		const older = loadOlderThreadMessages(thread);
		await flushPromises();

		closeView();
		mockedGetThreadMessages.mockResolvedValueOnce(page(5, 'R1'));
		const reopen = loadThreadMessages(thread);
		await flushPromises();
		expect(mockedGetThreadMessages).toHaveBeenCalledTimes(2);
		releaseOlder(5, 'R2');
		await Promise.all([older, reopen]);

		expect(mockedGetThreadMessages).toHaveBeenLastCalledWith({ tmid: thread.tmid, offset: 0, count: 50 });
		expect(areOlderThreadMessagesMissing(thread.tmid)).toBe(true);
	});

	it('drops a first page that lands after its thread view closed', async () => {
		const closeView = retainThreadPagination(thread.tmid);
		const releaseFirst = deferPage();
		const first = loadThreadMessages(thread);
		await flushPromises();

		closeView();
		releaseFirst(1, 'R1');
		await first;

		expect(dbBatch()).not.toHaveBeenCalled();
		await loadFirstPage(3, 'R1');
		expect(areOlderThreadMessagesMissing(thread.tmid)).toBe(true);
	});

	it('requests the first page again when the thread reopens while a reload is in flight', async () => {
		const closeView = retainThreadPagination(thread.tmid);
		await loadFirstPage(5, 'R1');
		const releaseReload = deferPage();
		const reload = loadThreadMessages(thread);
		await flushPromises();

		closeView();
		mockedGetThreadMessages.mockResolvedValueOnce(page(5, 'R1'));
		const reopen = loadThreadMessages(thread);
		releaseReload(5, 'R1');
		await Promise.all([reload, reopen]);

		expect(mockedGetThreadMessages).toHaveBeenCalledTimes(3);
		expect(areOlderThreadMessagesMissing(thread.tmid)).toBe(true);
	});
});

